select opened_cohort, avg_balance, checking_count from (select case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, round(avg(balance), 2) as avg_balance, count(case when account_type = 'CHECKING' then 1 end) as checking_count from accounts group by case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end) as t where avg_balance >= 39 order by avg_balance
